        return 0.0
    # The original parser reads the first match (message mode) or the last match
    # (string mode); both must be exactly the gold tree.
    if not _block_ok(blocks[0], gold_lines):
        return 0.0
    if not _block_ok(blocks[-1], gold_lines):
